    body: "偏差値とは、ある集団の平均点を50、標準偏差を10として個人の得点を変換した、標準得点の一種です。個人の得点が、所属する集団の中でどのあたりの位置にあるのかを、平均からの隔たりの度合いとして数値化して示すものです。\n\n計算式は「(個人の得点－平均点)÷標準偏差×10＋50」で表され、得点の分布がおおむね正規分布に近い形をとることを前提としています。平均点付近に多くの受験者の得点が集まり、平均から大きく離れるほど、その偏差値を取る受験者の数は少なくなっていきます。\n\n日本では高校・大学受験の模擬試験や学力検査の結果を示す指標として広く普及していますが、あくまで特定の集団内における相対的な位置を表す値にすぎず、絶対的な学力の到達度そのものを直接示すものではない点には注意が必要です。受験する母集団の学力層によって、同じ実力でも算出される数値が変動する点にも留意が必要で、模試の種類が違えば単純に数値を比較できないことにも注意が必要です。進路指導の場面では、こうした前提を踏まえた解釈が求められます。",
