    body: "指導と評価の一体化とは、評価を単に指導の結果を判定して終わらせるための手段とするのではなく、その後の指導の改善や児童生徒への支援に活かしていく、一連の循環的な過程として捉える考え方です。\n\n授業の中で目標を設定し、指導を行い、形成的評価によって児童生徒の学習状況をこまめに把握し、その結果を次の指導計画の見直しに反映させるというサイクルを繰り返し続けることが重視されます。学期末や単元末の総括的評価による成績づけだけに終わらせず、日々の授業改善そのものに評価を役立てる点が大きな特徴です。\n\n国立教育政策研究所が公表する学習評価に関する参考資料でも、この考え方は中心的な理念として掲げられており、目標準拠評価のもとで評価規準・評価基準をあらかじめ明確にし、指導計画と評価計画を一体的に設計することが求められています。評価が指導と切り離された作業にならないようにする点が、この理念の要となっており、テストの点数付けだけを目的化しないよう繰り返し強調されています。授業設計の段階から評価の場面を組み込む「逆向き設計」の発想とも関連が深い考え方です。",
