    body: "G理論（一般化可能性理論、Generalizability Theory）とは、古典的テスト理論を発展させた測定理論の一つで、分散分析の手法を用いて観測得点のばらつきを、受験者・評価者・項目・実施場面といった複数の要因に分解し、信頼性をより詳細に検討する理論です。\n\n分析は大きく2つの段階に分かれます。まず各変動要因が得点のばらつきにどの程度寄与しているかという分散成分を推定する「G研究」を行い、その結果をもとに、実際のテストや評価をどのような条件（必要な項目数や評価者数など）で実施すべきかを検討する「D研究」へと進んでいきます。\n\n単一の信頼性係数だけでは捉えきれない、評価者間のばらつきや課題間のばらつきなどを同時に扱えるため、パフォーマンス評価や小論文評価など、評価者の主観が入り込みやすい評価方法の測定精度を検討する際に、有効な手法として活用されています。医学教育におけるOSCE（客観的臨床能力試験）の評価者間信頼性の検討などにも応用されており、職業性ストレス調査票のような心理尺度の分析にも用いられています。",
    relatedSlugs: ["shinraisei", "koten-test-riron"],
    isCanonical: true,
    tags: ["一般化可能性理論", "分散分析", "評価者間信頼性"],
