    body: "標準得点とは、個人の得点から所属する集団の平均点を引き、その差を標準偏差で割ることによって求められる、異なる集団や検査の間でも比較可能な形に変換した得点のことです。集団の平均や散らばりが異なっても、共通の尺度で個人の位置を示すことができます。\n\n最も基本的な標準得点はZ得点（平均0、標準偏差1）ですが、負の値や小数を含み、教育現場では直感的に分かりにくいという難点があります。そのため実際には、平均50・標準偏差10に変換した偏差値や、知能検査などで用いられる平均100・標準偏差15の偏差知能指数といった形に加工して使われることが一般的です。\n\n標準得点を用いることで、実施回や問題内容が異なる検査の結果同士を共通の尺度で比較したり、国語と算数のように性質の異なる複数の教科・領域の成績を横断的に比較したりすることが可能になります。心理検査や知能検査の結果報告でも、標準得点は基本的な表記方法として用いられており、支援の必要性を判断する際の客観的な手がかりにもなります。分布の形が正規分布から大きく外れる場合には、変換の解釈に注意が必要とされています。",
