    body: "顔面妥当性とは、テストや評価項目が、測定しようとしている内容を測定しているように受検者や利用者の目に「見える」程度を指す概念です。内容的妥当性や構成概念妥当性のように統計的・専門的な検証手続きを経るものとは異なり、あくまで表面的な印象に基づく主観的な判断であるという特徴があります。\n\nこの妥当性は本来的に主観的であるため学術的には軽視されがちですが、受検者の動機づけや協力的な取り組み姿勢に影響するという実務上の意味を持ちます。テストの項目が測定目的と無関係に見えると、受検者は真剣に回答しなかったり不信感を抱いたりする可能性があり、結果としてデータの質が低下する恐れがあります。\n\nそのため、顔面妥当性は他の妥当性を担保する十分条件ではないものの、構成概念妥当性を確立するための前提条件の一つとみなされることがあります。教育評価の現場では、テストや質問紙を作成する際に、専門的な妥当性検証とあわせて、受検者にとって内容が自然で納得しやすいかという観点からの見直しも重要とされています。",
