    body: "調査書(内申書)とは、在籍する学校が作成し、進学先の学校に提出する書類で、各教科の評定(成績)や出欠状況、部活動や委員会活動などの学校生活の様子が記載されています。俗に「内申点」と呼ばれるのは、この調査書に記される各教科の評定そのもの、あるいはそれらを一定の方法で数値化・合計したものを指します。\n\n高校入試や大学入試において重視される「評定平均」は、在学期間中の全科目の評定の合計値を科目数で割って算出される数値で、学校推薦型選抜(指定校推薦・公募推薦)や総合型選抜では、出願条件として一定以上の評定平均が求められることが少なくありません。これに対し、学力検査の得点を主な資料とする一般選抜では、調査書の比重は相対的に小さくなる傾向があります。\n\n調査書は、日々の授業態度や提出物、定期考査の結果などを踏まえた観点別学習状況の評価を基礎として作成されるため、単発のテスト結果だけでは測れない学習の過程や継続的な取り組みを進学先に伝える役割を担っています。一方で、評定のつけ方は学校や教員によって差が生じうるため、公平性の確保が課題として指摘されることもあります。",
