    body: "コンピテンシーベース評価とは、単に知識や情報をどれだけ身につけているかを測るのではなく、その知識や技能を実際の課題解決場面でどのように活用し、資質・能力(コンピテンシー)としてどれだけ発揮できたかに着目する評価の考え方です。コンピテンシーという概念は、1970年代にアメリカの心理学者マクレランドが、高い業績を上げる人材に共通する行動特性として提唱したことに由来します。\n\n教育の文脈では、この考え方はコンテンツベース(内容重視)の評価と対比され、パフォーマンス評価や真正の評価と密接に関連づけて論じられます。ペーパーテストで知識の再生を確認するだけでなく、実社会に近い文脈で課題に取り組ませ、その過程や成果物から思考力・判断力・表現力などの発揮の様子を評価しようとする点が特徴です。\n\nコンピテンシーベース評価を機能させるには、何をもって資質・能力の発揮とみなすかという評価規準を具体的に定める必要があり、その手段としてルーブリックがしばしば併用されます。学習指導要領が「資質・能力の三つの柱」を掲げる中で、日本の学校教育においてもコンピテンシーベースの評価観への転換が求められる場面が増えています。",
