    body: "到達度評価は、教育目標の達成基準をあらかじめ具体的に設定し、それに対する学習者の到達状況を「達成」か「未達成」かという形で判定する評価方法である。集団内での相対的な位置づけによって成績を決める相対評価（集団準拠評価）とは異なり、他の学習者との比較を行わず、各学習者が目標にどれだけ近づいたかを個別に評価する点に特徴がある。\n\n到達度評価は1960年代から1970年代にかけて、相対評価に基づく評定（いわゆる「5段階相対評価」）が学習者間の過度な競争を助長するといった批判を背景に、日本の教育評価運動の中で普及した。到達度評価と、今日広く用いられている「目標に準拠した評価」は、いずれも目標を基準に評価するという点で共通しており、しばしば同義的に用いられるが、到達度評価はより厳密に到達・未到達の二値的判定や到達基準の明確化を重視する立場として位置づけられることが多い。\n\n現在、日本の学校における学習評価のスタンダードは「目標に準拠した評価」（いわゆる絶対評価）であり、観点別学習状況の評価もこの考え方に基づいて行われている。到達度評価はその理論的源流であり、目標に基づく評価という発想を教育現場に定着させる上で大きな役割を果たした。",
    relatedSlugs: ["zettai-hyoka", "sotai-hyoka", "kanten-betsu-hyoka", "gakushu-hyoka-sankanten"],
