    body: "TALIS（Teaching and Learning International Survey、OECD国際教員指導環境調査）は、OECDが実施する世界最大規模の教員・校長を対象とした国際調査である。2008年に第1回調査が実施され、その後2013年、2018年、2024年と概ね5〜6年周期で実施されている。調査対象は主に中学校段階（一部で初等・高校段階も含む）の教員と校長であり、質問紙への回答を通じて職場環境や職務満足度、教員の意識や実践を把握する。\n\n2024年調査（結果は2025年公表）には過去最多となる55の国・地域が参加し、約17,000校、約28万人の教員を対象に実施された。調査の柱は、教員の学歴・初任者研修などの養成過程、継続的な専門性開発（研修）、授業実践、労働環境や雇用条件、職務満足度・ウェルビーイング、学校運営や自律性などであり、近年ではAIの教育利用や、多様な背景を持つ児童生徒への対応、持続可能性教育といった新しいテーマも取り上げられている。\n\nTALISはPISAが児童生徒の学力を測定するのに対し、教える側である教員・校長の実態や意識に焦点を当てる点に特徴があり、教員の労働環境改善や教員政策、教員養成のあり方を検討する際の基礎資料として各国の教育政策に活用されている。",
