    body: "NAEP（National Assessment of Educational Progress）は、米国において1969年以来継続的に実施されている、全米の教育状況を測る代表的な学力調査であり、「全米の通信簿（The Nation's Report Card）」の愛称で知られる。連邦議会の授権に基づき、Governing Board（全米評価管理委員会）の監督のもと、全米教育統計センター（NCES）が実施する。\n\n調査は主に4年生・8年生・12年生を対象に、全50州、プエルトリコ、コロンビア特別区、国防総省関係学校（DoDEA）から抽出された代表サンプルに対して実施され、数学、読解、作文、理科、米国史、公民（シビックス）など幅広い教科領域における児童生徒の知識・技能を測定する。個々の児童生徒や学校の成績を評価するものではなく、あくまで集団としての達成状況を把握することを目的とする点が特徴である。\n\nNAEPの結果は、社会経済的背景、人種・民族、地域、公立・私立の別などの属性ごとの学力達成の傾向や経年変化を明らかにし、州間比較を可能にする「共通のものさし」として、米国の教育政策・アカウンタビリティ論議における最も重要な基礎データの一つとなっている。",
