    body: "ICILS（International Computer and Information Literacy Study、国際コンピュータ・情報リテラシー調査）は、国際教育到達度評価学会（IEA）が実施する国際比較調査であり、情報通信技術（ICT）が社会に浸透する中で、人々がデジタル社会に効果的に参加するために必要な能力をどの程度身につけているかを把握することを目的として開発された。対象は主に中学2年生（8年生）段階の生徒である。\n\n調査はコンピュータ上で実施され、コンピュータ・情報リテラシー（CIL：情報の収集・整理、情報の作成、デジタルコミュニケーションなど、基本的なICT活用を超えた能力）と、計算論的思考力（CT：問題を概念化し解決策を具体化する力）の2領域を測定する。2013年の第1回調査は21の国・地域が参加してCILを中心に実施され、2018年の第2回調査ではCTがオプション要素として追加された。第3回調査は2023年に実施されている。\n\nICILSは、PISAの読解力・数学的リテラシー・科学的リテラシーやTIMSSの理数系学力と並び、21世紀に必要とされるデジタル関連の能力を国際的に比較する枠組みとして位置づけられ、各国のICT教育政策やカリキュラム、教員研修のあり方を検討する基礎資料として活用されている。",
