    body: "ベンチマーク評価とは、学期末や年度末に実施される総括的評価（サマティブ・アセスメント）だけに頼るのではなく、単元の区切りや一定の期間（月ごと・学期の中間点など）ごとに、あらかじめ定めた学力の指標（ベンチマーク）に照らして児童生徒の到達状況を継続的に測定する評価方法である。多くの場合、学区や学校単位で共通化・標準化されたテストを用い、経年比較や学級間・学校間の比較が可能な形式で実施される。\n\nベンチマーク評価は、その位置づけとして形成的評価と総括的評価の中間に位置するとされることが多い。個々の授業内で行う小刻みな形成的評価に比べて実施頻度は低いものの、学年末の総括的評価を待たずに定期的にデータを収集するため、学期の途中で指導計画を軌道修正したり、つまずきのある児童生徒を早期に発見して個別支援につなげたりする目的で活用される。\n\n米国の学区などでは、教育委員会や学校が独自にベンチマークテストを開発・実施し、その結果を教員の授業改善や学校全体のカリキュラムマネジメントに活用する事例が広く見られる。継続的なデータに基づく意思決定を可能にする一方、テストの実施頻度が過度に増えることで授業時間が圧迫される「テスト漬け」への懸念も指摘されている。",
