    title: "標準設定法（アンゴフ法）",
    reading: "ひょうじゅんせっていほう",
    kana: "ひ",
    categories: ["evaluation"],
    summary:
      "資格試験や検定試験などで合格・不合格を分ける「カットスコア（合格基準点）」を、専門家の判断に基づいて客観的・体系的に設定する手続き。代表的手法がアンゴフ法。",
    body: "標準設定法（standard setting）とは、テストの得点のうち、合格・不合格や到達・未到達といった区分を分ける基準点（カットスコア）を、恣意的にではなく、体系的かつ客観的な手続きによって定める方法の総称である。資格試験や免許試験、認定試験など、特定の基準を満たしているかどうかの判定（合否判定）が重要な意味を持つ試験で広く用いられる。\n\n代表的な手法にアンゴフ法（Angoff法）がある。これは1971年にウィリアム・アンゴフによって提案された手法で、当該分野の専門家（SME：Subject Matter Experts）から成るパネルが、各設問について「ぎりぎり合格ラインにある受検者（最小限に有能な受検者）がその項目に正答する確率」を0〜100%で評定し、パネル全員の評定の平均値を積み上げて試験全体のカットスコアを算出する。原法がそのまま用いられることは少なく、実務では複数回の評定とデータへのフィードバックを組み合わせた「修正アンゴフ法」が最も広く使われている。\n\n標準設定法の利点は、当該分野に精通した専門家の専門的判断を体系的な手続きに落とし込むことで、カットスコアの妥当性と説明責任を確保できる点にある。一方で、専門家パネルの構成や評定の主観性がカットスコアに影響を与えうるため、複数の標準設定法の結果を照合したり、パネルの評定の一貫性を統計的に検証したりする工夫が行われている。",
    relatedSlugs: ["zettai-hyoka", "hyotei-shakudo-ho", "test-battery"],
    isCanonical: true,
