    summary:
      "IEAが実施する、シティズンシップ・公民教育に特化した唯一の大規模国際調査。中学生の公民的知識や政治参加への態度・意識を国際比較する。",
    body: "ICCS（International Civic and Citizenship Education Study、国際シティズンシップ・公民教育調査）は、国際教育到達度評価学会（IEA）が実施する国際調査であり、シティズンシップ教育・公民教育に特化した世界で唯一の大規模な国際比較調査である。1999年に実施された市民性教育調査（CIVED）を直接の前身とし、その理論的枠組みを土台としている。\n\nICCSは、民主主義や市民参加のあり方が変化する中で、若者がどのように市民としての役割を担う準備をしているかを検証することを目的とし、中学校段階（8年生前後）の生徒を対象に、公民・シティズンシップに関する概念や課題についての知識・理解を測定するとともに、政治参加や社会参加に対する生徒の信念、態度、行動についても調査する。あわせて、公民教育のカリキュラムや教員の資質・経験、学校の環境、家庭や地域社会の支援状況といった背景要因に関する詳細な文脈データも収集する。\n\n直近のICCS 2022には22か国・2州が参加し、約3,400校の約8万2千人の生徒と約4万人の教員が調査対象となった。次回調査はICCS 2027として計画されている。日本は本調査に参加していないが、諸外国におけるシティズンシップ教育の内容・方法・成果を比較検討する際の国際的な参照枠として、教育学研究や政策論議で取り上げられることがある。",
