    body: "評価者バイアス（評定誤差、rater error）とは、パフォーマンス評価や作文・小論文の採点、面接評価など、評価者の主観的判断を伴う評価場面において、評価者の認知的な傾向によって評定結果が系統的に歪められる現象の総称である。代表的なパターンとして、被評価者の一つの優れた（あるいは劣った）特徴に引きずられて他の側面まで同じように高く（低く）評価してしまう「ハロー効果」、全体的に甘く評定してしまう「寛大化傾向」、逆に厳しく評定してしまう「厳格化傾向」、極端な評価を避けて評定尺度の中央付近に評定を集中させてしまう「中心化傾向」、直前に評価した対象との比較によって評定がゆがむ「対比誤差」などが知られている。\n\nこうした評定誤差は、評価者間の一貫性（評価者間信頼性）を低下させ、評価結果の公平性や妥当性を損なう要因となる。そのため、ルーブリック（評価基準表）のように評価の観点と水準を具体的に言語化した基準を用いること、複数の評価者による採点を行い評定を突き合わせる合議・調整のプロセスを設けること、評価者に対する事前の研修（モデレーション）によって評価基準の解釈をそろえることなどが、評定誤差を低減するための対策として広く行われている。\n\nパフォーマンス評価やルーブリック評価、ポートフォリオ評価のように評価者の判断が結果を大きく左右する評価方法が普及するにつれて、評価者バイアスをいかに統制し、評価の信頼性と妥当性を確保するかは、教育評価における重要な実務的・研究的課題となっている。",
