    body: "指導要録は、児童生徒の学籍並びに指導の過程及び結果の要約を記録し、その後の指導や外部に対する証明（転学、進学、卒業の証明など）に役立てるための原簿です。学校教育法施行規則に基づいて校長が作成する義務を負い、様式は設置者である教育委員会などが定めます。「学籍に関する記録」と「指導に関する記録」の二つから成り、前者は20年間、後者は5年間の保存が定められています。\n\n歴史的には、1881年（明治14年）の学事表簿様式の制定にさかのぼり、1900年（明治33年）の小学校令施行規則で「学籍簿」という名称の全国統一様式が定められました。戦後は1949年に「指導要録」と改称され、学習指導要領の改訂に合わせて記載内容が見直されてきました。直近では2019年3月29日付の文部科学省通知により、観点別学習状況の評価が「知識・技能」「思考・判断・表現」「主体的に学習に取り組む態度」の3観点に整理されています。\n\n指導要録は、保護者に学習状況を伝える通知表とは法的な位置づけが異なります。通知表に作成義務や法的根拠はありませんが、指導要録は法定の公簿です。近年は教員の負担軽減や校務のデジタル化の観点から、様式の簡素化や電子化の議論も進んでいます。評価の信頼性を支える記録として、観点別評価や個人内評価の考え方と合わせて理解することが大切です。",
