    body: "通知表は、通信簿、通知簿、あゆみなど学校ごとに名称が異なる文書で、保護者に対して子どもの学習指導の状況を連絡し、家庭の理解や協力を求める目的で作成されます。文部科学省の説明でも、通知表には法的な根拠はなく、作成するかどうか、またその様式や内容は学校長の裁量に任されるとされています。法定の公簿である指導要録とは、この点で明確に区別されます。\n\n通知表の源流は明治期にさかのぼり、1891年（明治24年）の「小学校教則大綱ノ件説明」に、教授上の記述に加えて児童の心性や行為などを記載して学校と家庭の連携を図ることが示されたのが、早い時期の公的な言及とされています。指導要録との関係は時代によって扱いが変わり、1980年改訂の頃には両者の記載内容を一致させる考え方も示されましたが、その後は指導要録の様式をそのまま通知表に転用することは適切でないとされるようになりました。\n\n現在の通知表は、観点別学習状況の評価や評定、所見欄、出欠の記録などで構成されることが多く、学習評価の考え方（目標に準拠した評価）に沿って作られるのが一般的です。保護者との信頼関係に直結する文書であるため、評価の根拠を説明できること、子どもの伸びを伝える個人内評価を適切に添えることが重要とされています。",
