    body: "大学入試センター試験は、大学入試センターが作成・実施し、1990年1月から2020年1月まで実施された大学入学者選抜のための共通試験です。前身は、1979年に始まった国公立大学共通第1次学力試験（共通一次試験）で、その実施のために1977年に大学入試センターが設置されました。共通一次は、各大学が個別に出題していた時代に高校の学習範囲を超える難問・奇問が出されることがあるという問題を改善し、基礎的な学力を一定の水準で判定することをねらいとしていました。\n\nセンター試験への移行により、国公立大学だけでなく多くの私立大学も試験結果を利用できるようになり、利用大学・短期大学の数は大きく広がりました。2020年1月の試験では約850の大学・短大が利用を予定していたとされています。一方、共通一次の導入後に大学の序列化と受験競争が一層進んだという批判や、マークシート方式で知識の再生に偏るという指摘が続きました。\n\n中央教育審議会は2014年の答申などで、知識の暗記や再生に偏る入試から、思考力・判断力・表現力を含む学力の三要素を多面的に評価する入試への転換を求め、2021年1月から大学入学共通テストに置き換えられました。センター試験の歴史は、日本の大学入試が「共通試験で基礎学力、個別試験で独自の評価」という二段階をどう発展させてきたかを示しています。",
