    body: "学校推薦型選抜は、出身学校の校長が責任をもって推薦する生徒を対象に、主として調査書などの出願書類で評価する大学入学者選抜の方式です。2021年度入学者選抜から、大学入学共通テストへの移行に合わせた入試区分の見直しにより、従来の「推薦入試」が「学校推薦型選抜」に、「AO入試」が「総合型選抜」に、「一般入試」が「一般選抜」にそれぞれ名称変更されました。\n\n実施にあたっては、学力の三要素（知識・技能、思考力・判断力・表現力、主体性を持って多様な人々と協働して学ぶ態度）を適切に評価することが求められ、調査書や推薦書だけでなく、小論文、面接、プレゼンテーション、教科・科目のテスト、資格・検定試験の成績、大学入学共通テストなどを組み合わせて評価します。大学が指定した高校の生徒だけが出願できる指定校制と、条件を満たせば誰でも出願できる公募制があり、公募制を総合型選抜に分類するなど、区分の扱いは大学によって異なります。\n\n推薦による入学者の割合は近年高まり、一般選抜の受験競争を避けるために使われる面もあるなど、早期に進学先が決まることによる高校3年生の学習意欲への影響が指摘されてきました。評価の公正性を保つうえで、調査書の学習成績の状況や内申点の信頼性、評価の基準の一貫性が重要な論点となります。",
