    body: "高大接続改革の柱として、大学入学共通テストでは、英語の4技能（読む・聞く・話す・書く）を評価するため英検やGTECなどの民間の資格・検定試験の成績を活用する「大学入試英語成績提供システム」と、思考力・判断力・表現力を評価するための国語・数学の記述式問題の導入が予定されていました。しかし、試験会場や受験料の地域間・経済格差、民間試験の成績をCEFR（ヨーロッパ言語共通参照枠）の段階に対応づける妥当性への疑問など、公平性をめぐる批判が強まりました。\n\n文部科学省は2019年11月1日、英語民間試験の2020年度（2021年1月実施の共通テスト）からの活用を見送り、2024年度の入試からの活用に向けて検討会議を設けて議論するとの方針を示しました。その背景に、当時の文部科学大臣の「身の丈」発言への批判があったと報じられています。続いて2019年12月17日、国語と数学の記述式問題についても、採点の公平性や自己採点との不一致の懸念から、導入を見送ると表明されました。\n\nこの経緯は、大規模試験で多面的な能力を評価しようとするとき、評価の妥当性・信頼性・公平性をどう両立させるかという難題を示しています。数十万人規模の記述答案を短期間で一貫した基準で採点する難しさ、異なる民間試験の得点を比較可能にする等化の問題、受験機会の均等といった論点は、評価者間信頼性やテスト等化といった測定理論の観点からも検討されています。",
