    body: "ピア・アセスメントは、学習者が仲間の成果物やパフォーマンスを評価基準に照らして評価し、フィードバックを与え合う活動です。トッピング（Keith Topping）が1998年に『Review of Educational Research』誌で発表した大学・短大での学生間評価に関する文献レビューは、この分野の代表的な研究で、さまざまな適用で信頼性と妥当性が十分であり、点数や成績を用いた仲間評価に形成的効果があること、その効果は教師による評価と同等かそれ以上であることを報告しました。なお同論文は、設計の違いを整理する17の変数から成る類型も提示しています。\n\n効果としては、評価基準への理解が深まること、他者の成果から学べること、評価する側もされる側も成果物を振り返る機会を得ること、教師が一人で行う評価の負担を補えることなどが挙げられます。ルーブリックを使うと評価の観点が明確になり、学習者間の判断のばらつきも抑えられます。プレゼンテーション、レポート、グループ活動などで活用されます。\n\n一方で、友人関係による評価の偏り、評価能力の個人差、仲間に低い評価をつけることへの抵抗、成績に直結させたときの不公平感などの課題があります。匿名化、基準の事前共有、評価練習、成績算定への使用の限定などの工夫が必要です。自己評価とあわせて、学習者が評価に主体的に関与する学習のための評価の一形態といえます。",
