    body: "テストを構成する個々の設問がどの程度難しいかを示す統計的指標である。古典テスト理論の枠組みの中で確立され、受検者集団の能力水準や問題自体の難易度を客観的に把握するための基礎的な教育測定尺度として長年にわたり活用されてきた。\n\n算出は主に対象集団全体における正答者の割合である通過率によって行われ、値が1に近いほど平易であり、ゼロに近いほど困難であることを意味する。学校の定期考査や標準化テストでは、各項目の正答率を算出して極端に正答率が高い問題や低い問題を特定し、意図した難易度配分になっているかを点検する。\n\n項目困難度を把握することで、教師は授業で教えた学習内容がどの程度定着しているかを設問ごとに見極めることができる。正答率が著しく低い項目は指導計画や教授法の見直しに直結し、形成的評価としての指導改善や作問技術の向上に大きく貢献する。",
