    body: "テストの個々の設問が受検者の総合的な学力や能力差を的確に見分けている度合いを示す指標である。近代的なテスト理論の発展に伴い、良質な測定用具を構築するために不可欠な項目分析の根幹として位置づけられてきた。\n\n算出方法としては、テスト全体の総得点が高い上位群と低い下位群を抽出し、上位群の正答率から下位群の正答率を差し引く識別指数や、項目得点とテスト総得点との相関係数を用いる。値が正で十分に大きい項目は優秀な識別力を持ち、値がゼロや負を示す項目は問題の不備や誤答の誘導が疑われる。\n\n識別力の分析を行うことで、学力差を正しく測れていない欠陥問題を排除し、評価の信頼性を高めることができる。また、教師が作問の妥当性を省察し、学習指導においてどの概念が学力定着の分岐点となっているかを特定する貴重な手がかりとなる。",
