    body: "項目反応理論において、各設問が持つ測定の精度を受検者の能力水準の関数として表現した数理的手法である。受検者集団に依存せず問題固有の測定精度を評価できる理論として、20世紀後半以降の大規模学力測定で急速に普及した。\n\n項目情報関数の値は項目特性曲線の傾きや母数から導かれ、情報量が大きいほどその能力値周辺での測定誤差が小さいことを意味する。設問の識別力が高いほど曲線の傾斜が急になり、特定の能力水準において非常に多くの測定情報を提供できる。\n\nコンピュータ適応型テストでは、受検者の推定能力に応じて情報関数が最大となる項目を動的に出題することで、少ない設問数で極めて高い測定精度を実現する。学習者一人ひとりの能力に応じた個別最適な評価を支える基盤技術となっている。",
