    body: "多肢選択式テストにおいて、正答以外の選択肢である誤答肢がどの程度適切に選ばれているかを調べる項目分析の手法である。客観テストの信頼性と妥当性を担保するため、20世紀初頭の教育測定運動の中で作問改善の基盤として開発された。\n\n分析では受検者を総得点に基づいて上位群や中位群、下位群などに区分し、各群がどの選択肢を選んだかの頻度分布を集計する。適切な誤答肢は主に下位群によって選ばれるべきであり、誰にも選ばれない無効な選択肢や、上位群が多く選んでしまう不適切な選択肢を検出して修正する。\n\n特定の誤答肢に児童生徒の選択が集中している場合、共通するつまずきや概念的な誤解が存在することを突き止めることができる。単なる合否判定を超えて、授業における弱点の補正や指導内容の再構成を促す形成的な教育価値を持っている。",
