    body: "記述式や論述式の試験において、採点者の主観によるブレを防ぎ、評価の一貫性を確保するために作成される詳細な判定指針である。主観的評価に伴う評定誤差を最小限に抑え、受検者の思考力や表現力を公平に測る必要性から確立されてきた。\n\n作成手順として、問われるべき思考要素や論理展開を複数の観点に分解し、部分点の配分や許容される表記の範囲を具体的に設定する。典型的な正答例だけでなく、想定される不完全な解答例や誤答の類型を網羅し、採点者が迷う境界事例の判定基準をあらかじめ定めておく。\n\n採点基準表を事前に児童生徒に提示したり採点後に返却したりすることで、自らの論述のどこに課題があったのかを自己評価できる。思考力や判断力の育成に向けた明確な目標提示となり、日々の論述指導と学習評価の質を向上させる。",
