    body: "一人の採点者が同じ受検者の答案や実技演技を評価した際に、時間や状況の違いを超えてどれだけ同一の判定を下せるかを示す信頼性の指標である。主観的評価が採点者の疲労や気分の変化によって揺らぐという課題に対し、採点の一貫性を点検するために確立された。\n\n検証手順として、採点済みの答案の中から一部を無作為に抜き出し、一定期間を置いた後に採点者自身に元の採点結果を伏せた状態で再採点を行わせる。1回目と2回目の採点結果の相関係数や一致度を算出し、評価基準が採点者の内部で安定して機能しているかを確認する。\n\n評価者内信頼性を高める訓練を経ることで、教師は自らの採点基準を客観的に自覚し、気分や疲労によるブレを自律的に抑えられるようになる。児童生徒への指導において、常に公正でぶれない助言を与えることが可能となり、学習者からの信頼を高める。",
