    body: "テストが測定しようと意図している理論的・心理的な構成概念を正しく測定している度合いを指す。クロバックらが提唱して以来、単なる実務的基準との相関を超えて、テスト得点の解釈が教育理論に基づき科学的に支持されるかを問う中核的妥当性となった。\n\n検証には、同一概念を測る他のテストとの高い相関を確認する収束的妥当性と、無関係な概念を測るテストとの間に相関が見られないことを確認する弁別的妥当性の双方が求められる。多特性多方法行列法や確認的因子分析などの統計手法を用いて、理論モデルの適合度を多角的に検証する。\n\n構成概念妥当性を明らかにすることで、テスト結果が思考力や表現力といった目指す資質・能力を捉えているかが理論的に保証される。教育現場における教育課程の評価や新指導法の実践研究において、確証ある知見を提供する役割を担っている。",
