    body: "新しい指導法や教育施策の効果を測定するため、対象を無作為に介入群と対照群に割り振って比較する科学的実験手法である。医学や社会科学の実験計画法に起源を持ち、指導法以外の背景要因を統計的に統制して真の教育効果を特定する基準として位置づけられている。\n\n学校や学級などの単位を乱数を用いて無作為に割り当て、一方の集団にのみ特定の教材や指導法を実施し、他方には従来通りの指導を行う。介入前後の学力や学習態度の変化量を測定し、両群の平均値の差を統計的に検定することで介入自体の効果量を精密に算出する。\n\n家庭環境や生来の能力などの要因による見かけの相関を完全に排除できるため、極めて信頼性の高い証拠が得られる。効果的な教育実践の選別と教育予算の適正な配分に決定的な根拠を提供し、教育界における科学的な指導改善の進展を強力に後押しする。",
