    body: "教育政策の導入前後における対象集団の変化と、未導入の比較集団の変化との差を比較することで政策効果を推定する統計手法である。全校一斉導入や倫理的制約により無作為割り振りが困難な教育現場において、因果効果を厳密に抽出する準実験の代表的手法である。\n\n施策導入前の両集団の学力水準などの差と、導入後の差の推移を数理モデルで分析する。両集団がもし施策なしであれば同一の時間的推移をたどるという共通傾向の仮定のもとで、時間経過による共通要因と集団固有の固定効果を相殺し、介入の純粋な効果を算出する。\n\n少人数学級化や放課後学習支援など、自治体単位で導入された教育施策の真の有効性を既存の統計データから客観的に評価できる。単なる前後比較の誤りを防ぎ、証拠に基づいた教育施策の立案と教育資源の効果的な再配分を実現する上で極めて有用である。",
