    body: "試験の点数などの明確な基準値によって支援や選抜の対象が決まる制度を利用し、施策の因果効果を測定する準実験手法である。1960年代に教育研究の分野で考案され、倫理的な制約から無作為な選抜ができない教育施策を厳密に評価する枠組みとして確立された。\n\n基準値の直上に位置する合格者と、直下に位置する不合格者は、資質や背景において統計的にほぼ同等とみなすことができる。この境界付近における教育的処置の有無による学習成果の段差を回帰分析によって検出し、選抜や特別支援が及ぼした因果的影響を精密に推定する。\n\n人為的な選抜基準を逆手に取り、補習教育や奨学金給付といった重点施策が本当に学力向上に寄与したかを高い確信度で判定できる。学習指導や選抜制度の妥当性を客観的に検証し、真に必要な支援を的確に届けるための制度設計と改善に大きく寄与する。",
