    body: "評定の極値判定基準とは、段階評定（一般に5段階）において最上位の「5」および最下位の「1」を決定する際の明確な基準である。集団準拠評価（相対評価）から目標準拠評価（絶対評価）への全面移行に伴い、極端な評定を付与する際の客観的な根拠と説明責任の確保が強く求められるようになった。\n\n各教科の観点別評価（知識・技能、思考・判断・表現、主体的に学習に取り組む態度）の組み合わせにおいて、例えば全観点がAで顕著な達成が認められる場合に「5」、全観点がCで基礎的基本的事項の未習得が顕著な場合に「1」とする基準を校内規程で明文化する。判定に疑義がある事例は成績会議やモデレーション協議で合議する。\n\n安易な評定の偏りや情実採点を排除し、進学や就職に直結する成績の公的信頼性を確保する。特に段階1と判定された生徒に対しては即座に補習や個別支援を実施する指導改善の契機となり、誰一人取り残さない指導を支える制度的担保として機能する。",
