    body: "出席停止・忌引等の評価上の取り扱い規程とは、学校保健安全法に基づく出席停止や校則に定める忌引等により試験を受験できなかった児童生徒に対し、公正な評価を保障するための規則である。本人の責めに帰さない理由による欠席で不当な成績低下が生じるのを防ぎ、学習機会と評価の公平性を両立させる公教育の要請から制定された。\n\n対象生徒の定期考査欠席時には、追試験の実施、平素の小テストや提出物の成果、過去の考査得点から平均点比率を考慮した見込み点の算出など、明確な算定式を規程に基づいて適用する。成績一覧表には理由を明記し、職員会議等で審議を経て校長が決裁する。\n\n病気の発症時や家庭の非常時における学習者の不安を解消し、安心して療養や休養を取れる環境を整える教育的配慮として不可欠である。欠席期間中の学習補充や個別指導の機会を保障することで、学修成果を公平に評価し進路選択への悪影響を防ぐ役割を果たす。",
