    body: "定期考査における合理的配慮と個別調整とは、障害や疾病等のある児童生徒が能力を十全に発揮できるよう、試験の実施環境や形式を個別柔軟に調整する措置である。障害者差別解消法の施行やインクルーシブ教育の進展に伴い、学力評価の場における過重な負担を解消し、実質的な機会均等を保障する法的・教育的義務として定着した。\n\n個別の教育支援計画に基づき、本人や保護者との合意形成を経て調整内容を決定する。具体的な措置として、別室受験、試験時間の延長、拡大文字やルビ付き問題用紙の配付、音声読み上げや情報端末等の支援機器の使用、解答の口頭試問や代筆などが公正に実施される。\n\n単なる点数の優遇ではなく、学習者が本来備えている学力を障害の影響を排除して正確に測定・可視化する意義を持つ。配慮の結果を日常指導の個別最適化に反映させることで、自立と社会参加を支える公平な教育評価基盤を構築している。",
